"""Parity with the TypeScript engine: 1.180 golden cases generated by `src/engine/__tests__/golden-export.test.ts`.

The same inputs go through the Python engine; every number must match to the cent and every message to the word. Money in
the golden file is parsed as `Decimal`, so no float is involved in the comparison either.
"""

import json
import re
from decimal import Decimal
from pathlib import Path
from typing import Any

import pytest
from pydantic import TypeAdapter

from app.engine.calendar import upcoming_deadlines
from app.engine.irpf_investments import (
    Acoes,
    Aluguel,
    FundoAcoes,
    GanhoCapital,
    InvestmentIncome,
    Isento,
    RendaFixa,
    investment_tax,
)
from app.engine.money import allocate, mul_rate, to_cents
from app.engine.real_engine import RealEngine
from app.engine.reform import reform_taxes
from app.engine.result import EngineResult, InsufficientData, NoneFound, NotApplicable, Ok
from app.engine.rules_data import default_rulebook
from app.engine.types import CompanyProfile, MonthlyEntry, PersonProfile

GOLDEN = Path(__file__).parent / "golden" / "cases.json"
CASES: list[dict[str, Any]] = json.loads(GOLDEN.read_text(encoding="utf-8"), parse_float=Decimal)["cases"]
BOOK = default_rulebook()
# Ratios come out of a division: the TypeScript double and the Python Decimal agree to far more digits than anyone needs.
APPROX = {"effectiveRate", "deltaPct"}
# Known TypeScript defect: the Fator R opportunity raises the payroll exactly to the 28% threshold and the double comes out as
# 0.27999999999999997, so the TS engine drops the opportunity. With exact decimals the ratio is 28% and the opportunity exists
# (what the rule means). Python is right; the case is checked on its own below instead of against the TS answer.
TS_FLOAT_ARTIFACT = {"company-102"}


def snake(name: str) -> str:
    return re.sub(r"(?<!^)(?=[A-Z])", "_", name).lower()


def dec(value: Any) -> Decimal | None:
    return None if value is None else Decimal(str(value))


def company(d: dict[str, Any]) -> CompanyProfile:
    fields: dict[str, Any] = {}
    for key, value in d.items():
        if key == "series":
            fields["series"] = [
                MonthlyEntry(
                    e["month"],
                    dict(e.get("revenue", {})),
                    dec(e.get("purchases")),
                    dec(e.get("payroll")),
                    dec(e.get("proLabore")),
                )
                for e in value
            ]
        elif key in ("monthlyRevenue", "monthlyPurchases", "issRate", "profitMargin", "fap", "terceirosRate", "taxLossBalance"):
            fields[snake(key)] = dec(value)
        else:
            fields[snake(key)] = value
    return CompanyProfile(**fields)


def person(d: dict[str, Any]) -> PersonProfile:
    return PersonProfile(
        dec(d.get("annualGrossIncome")),
        dec(d.get("inssPaid")),
        d.get("dependents"),
        dec(d.get("healthExpenses")),
        dec(d.get("educationExpenses")),
        dec(d.get("privatePension")),
        dec(d.get("taxWithheld")),
    )


def investment(item: dict[str, Any]) -> InvestmentIncome:
    kind = item["kind"]
    if kind == "renda_fixa":
        return RendaFixa(Decimal(item["gain"]), item["daysHeld"])
    if kind == "fundo_acoes":
        return FundoAcoes(Decimal(item["gain"]))
    if kind == "acoes":
        return Acoes(Decimal(item["netGain"]), Decimal(item["monthSales"]))
    if kind == "ganho_capital":
        return GanhoCapital(Decimal(item["gain"]))
    if kind == "aluguel":
        return Aluguel(Decimal(item["received"]), Decimal(item["deductions"]))
    return Isento(Decimal(item["amount"]), item["product"])


def envelope(result: EngineResult[Any], dump: Any = None) -> dict[str, Any]:
    if isinstance(result, Ok):
        value = dump(result.value) if dump else result.value
        return {"status": "ok", "value": value}
    if isinstance(result, InsufficientData):
        return {"status": "insufficient_data", "missing": result.missing}
    if isinstance(result, NotApplicable):
        return {"status": "not_applicable", "reason": result.reason}
    assert isinstance(result, NoneFound)
    return {"status": "none_found"}


def jsonable(value: Any) -> Any:
    return TypeAdapter(type(value)).dump_python(value, mode="json", by_alias=True)


def same(expected: Any, actual: Any, path: str, key: str = "") -> list[str]:
    """Differences between a TypeScript value and the Python one, as readable lines (empty when they agree)."""
    if expected is None:
        return [] if actual is None else [f"{path}: expected nothing, got {actual!r}"]
    if isinstance(expected, dict):
        if not isinstance(actual, dict):
            return [f"{path}: expected an object, got {actual!r}"]
        out: list[str] = []
        for k, v in expected.items():
            out += same(v, actual.get(k), f"{path}.{k}", k)
        out += [f"{path}.{k}: unexpected {v!r}" for k, v in actual.items() if k not in expected and v is not None]
        return out
    if isinstance(expected, list):
        if not isinstance(actual, list) or len(actual) != len(expected):
            return [f"{path}: expected {len(expected)} items, got {actual if not isinstance(actual, list) else len(actual)}"]
        return [d for i, (e, a) in enumerate(zip(expected, actual, strict=True)) for d in same(e, a, f"{path}[{i}]")]
    if isinstance(expected, str):
        # Known TypeScript defect: a break-even quarter prints "R$ -0" (negated zero). Python prints "R$ 0".
        expected = expected.replace("R$ -0:", "R$ 0:")
    if isinstance(expected, bool | str):
        return [] if expected == actual else [f"{path}: expected {expected!r}, got {actual!r}"]
    # numbers: Decimal/int from the golden file against Decimal/str/int from Python
    try:
        want, got = Decimal(str(expected)), Decimal(str(actual))
    except Exception:
        return [f"{path}: expected the number {expected}, got {actual!r}"]
    if key in APPROX:
        return [] if abs(want - got) < Decimal("1e-9") else [f"{path}: expected ~{want}, got {got}"]
    return [] if want == got else [f"{path}: expected {want}, got {got}"]


def run(case: dict[str, Any]) -> Any:
    i = case["input"]
    kind = i["kind"]
    if kind == "company":
        engine = RealEngine(i["competence"], BOOK)
        profile = company(i["profile"])
        out: dict[str, Any] = {"diagnose": envelope(engine.diagnose(profile), jsonable)}
        out["opportunities"] = (
            envelope(engine.opportunities(profile), jsonable) if case["output"]["opportunities"] is not None else None
        )
        return out
    if kind == "person":
        return envelope(RealEngine(i["competence"], BOOK).diagnose_person(person(i["person"])), jsonable)
    if kind == "investment":
        return envelope(investment_tax(BOOK, i["competence"], investment(i["item"])), jsonable)
    if kind == "reform":
        data = i["input"]
        result = reform_taxes(
            BOOK,
            i["competence"],
            sales=Decimal(data["sales"]),
            creditable_purchases=Decimal(data["creditablePurchases"]),
            category=data.get("category"),
            cbs_reference_rate=dec(data.get("cbsReferenceRate")),
            ibs_reference_rate=dec(data.get("ibsReferenceRate")),
        )
        return envelope(
            result,
            lambda v: {
                "cbsCents": v.cbs_cents,
                "ibsCents": v.ibs_cents,
                "legacyShare": v.legacy_share,
                "pisCofins": v.pis_cofins,
            },
        )
    if kind == "to_cents":
        return to_cents(i["value"])
    if kind == "mul_rate":
        return mul_rate(i["cents"], i["rate"], i["mode"])
    if kind == "allocate":
        return allocate(i["total"], i["weights"])
    assert kind == "deadlines"
    return jsonable(upcoming_deadlines(i["regime"], i["from"], i["horizonDays"]))


def normalized(case: dict[str, Any], actual: Any) -> Any:
    """Investment `rate` and the like are Decimals in Python; the comparison is numeric, so nothing else to do here."""
    return actual


@pytest.mark.parametrize("kind", sorted({c["input"]["kind"] for c in CASES}))
def test_the_python_engine_matches_the_typescript_engine_case_by_case(kind: str) -> None:
    failures: list[str] = []
    cases = [c for c in CASES if c["input"]["kind"] == kind]
    for case in cases:
        expected = case["output"]
        if case["id"] in TS_FLOAT_ARTIFACT:
            expected = {"diagnose": expected["diagnose"], "opportunities": None}
        diffs = same(expected, normalized(case, run(case)), case["id"]) if case["id"] not in TS_FLOAT_ARTIFACT else []
        if diffs:
            failures.append("\n  ".join(diffs[:4]))
    assert not failures, f"{len(failures)} of {len(cases)} '{kind}' cases differ from the TypeScript engine:\n" + "\n".join(
        failures[:8]
    )


def test_the_golden_file_covers_every_kind_regime_and_state() -> None:
    kinds = {c["input"]["kind"] for c in CASES}
    assert kinds == {"company", "person", "investment", "reform", "to_cents", "mul_rate", "allocate", "deadlines"}
    companies = [c for c in CASES if c["input"]["kind"] == "company"]
    assert {c["input"]["profile"]["regime"] for c in companies} == {"simples", "presumido", "real", "mei"}
    assert {c["output"]["diagnose"]["status"] for c in companies} == {"ok", "insufficient_data", "not_applicable"}
    assert len(CASES) >= 1000


def test_the_documented_typescript_float_artifact_is_decided_in_favour_of_the_rule() -> None:
    case = next(c for c in CASES if c["id"] in TS_FLOAT_ARTIFACT)
    assert case["output"]["opportunities"] == {"status": "none_found"}  # what the TypeScript engine says
    assert same({"diagnose": case["output"]["diagnose"]}, {"diagnose": run(case)["diagnose"]}, case["id"]) == []
    engine = RealEngine(case["input"]["competence"], BOOK)
    result = engine.opportunities(company(case["input"]["profile"]))
    assert isinstance(result, Ok)
    item = result.value.items[0]
    assert item.id == "opp-fator-r" and item.status == "found" and item.assumptions and item.requires_validation
